class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Set<Long> blocked = new java.util.HashSet<>();
        for (int[] obstacle : obstacles) {
            blocked.add(key(obstacle[0], obstacle[1]));
        }

        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int direction = 0;
        int x = 0;
        int y = 0;
        int best = 0;

        for (int command : commands) {
            if (command == -2) {
                direction = (direction + 3) % 4;
            } else if (command == -1) {
                direction = (direction + 1) % 4;
            } else {
                for (int step = 0; step < command; step++) {
                    int nextX = x + directions[direction][0];
                    int nextY = y + directions[direction][1];
                    if (blocked.contains(key(nextX, nextY))) {
                        break;
                    }
                    x = nextX;
                    y = nextY;
                    best = Math.max(best, x * x + y * y);
                }
            }
        }

        return best;
    }

    private long key(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }
}

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Set<String> blocked = new java.util.HashSet<>();
        for (int[] obstacle : obstacles) {
            blocked.add(obstacle[0] + "," + obstacle[1]);
        }

        int x = 0;
        int y = 0;
        int dx = 0;
        int dy = 1;
        int best = 0;

        for (int command : commands) {
            if (command == -2) {
                int oldDx = dx;
                dx = -dy;
                dy = oldDx;
            } else if (command == -1) {
                int oldDx = dx;
                dx = dy;
                dy = -oldDx;
            } else {
                for (int step = 0; step < command; step++) {
                    int nextX = x + dx;
                    int nextY = y + dy;
                    if (blocked.contains(nextX + "," + nextY)) {
                        break;
                    }
                    x = nextX;
                    y = nextY;
                    best = Math.max(best, x * x + y * y);
                }
            }
        }

        return best;
    }
}

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Map<Integer, java.util.TreeSet<Integer>> byX = new java.util.HashMap<>();
        java.util.Map<Integer, java.util.TreeSet<Integer>> byY = new java.util.HashMap<>();
        for (int[] obstacle : obstacles) {
            byX.computeIfAbsent(obstacle[0], key -> new java.util.TreeSet<>()).add(obstacle[1]);
            byY.computeIfAbsent(obstacle[1], key -> new java.util.TreeSet<>()).add(obstacle[0]);
        }

        int x = 0;
        int y = 0;
        int direction = 0;
        int best = 0;

        for (int command : commands) {
            if (command == -2) {
                direction = (direction + 3) % 4;
            } else if (command == -1) {
                direction = (direction + 1) % 4;
            } else if (direction == 0) {
                int target = y + command;
                java.util.TreeSet<Integer> ys = byX.get(x);
                Integer block = ys == null ? null : ys.ceiling(y + 1);
                y = block != null && block <= target ? block - 1 : target;
            } else if (direction == 1) {
                int target = x + command;
                java.util.TreeSet<Integer> xs = byY.get(y);
                Integer block = xs == null ? null : xs.ceiling(x + 1);
                x = block != null && block <= target ? block - 1 : target;
            } else if (direction == 2) {
                int target = y - command;
                java.util.TreeSet<Integer> ys = byX.get(x);
                Integer block = ys == null ? null : ys.floor(y - 1);
                y = block != null && block >= target ? block + 1 : target;
            } else {
                int target = x - command;
                java.util.TreeSet<Integer> xs = byY.get(y);
                Integer block = xs == null ? null : xs.floor(x - 1);
                x = block != null && block >= target ? block + 1 : target;
            }
            best = Math.max(best, x * x + y * y);
        }

        return best;
    }
}

class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        java.util.Map<Integer, java.util.List<Integer>> byX = new java.util.HashMap<>();
        java.util.Map<Integer, java.util.List<Integer>> byY = new java.util.HashMap<>();
        for (int[] obstacle : obstacles) {
            byX.computeIfAbsent(obstacle[0], key -> new java.util.ArrayList<>()).add(obstacle[1]);
            byY.computeIfAbsent(obstacle[1], key -> new java.util.ArrayList<>()).add(obstacle[0]);
        }
        for (java.util.List<Integer> values : byX.values()) {
            java.util.Collections.sort(values);
        }
        for (java.util.List<Integer> values : byY.values()) {
            java.util.Collections.sort(values);
        }

        int x = 0;
        int y = 0;
        int direction = 0;
        int best = 0;

        for (int command : commands) {
            if (command == -2) {
                direction = (direction + 3) % 4;
            } else if (command == -1) {
                direction = (direction + 1) % 4;
            } else if (direction == 0) {
                y = movePositive(y, y + command, byX.get(x));
            } else if (direction == 1) {
                x = movePositive(x, x + command, byY.get(y));
            } else if (direction == 2) {
                y = moveNegative(y, y - command, byX.get(x));
            } else {
                x = moveNegative(x, x - command, byY.get(y));
            }
            best = Math.max(best, x * x + y * y);
        }

        return best;
    }

    private int movePositive(int current, int target, java.util.List<Integer> obstacles) {
        if (obstacles == null) {
            return target;
        }
        int index = upperBound(obstacles, current);
        if (index < obstacles.size() && obstacles.get(index) <= target) {
            return obstacles.get(index) - 1;
        }
        return target;
    }

    private int moveNegative(int current, int target, java.util.List<Integer> obstacles) {
        if (obstacles == null) {
            return target;
        }
        int index = lowerBound(obstacles, current) - 1;
        if (index >= 0 && obstacles.get(index) >= target) {
            return obstacles.get(index) + 1;
        }
        return target;
    }

    private int lowerBound(java.util.List<Integer> values, int target) {
        int left = 0;
        int right = values.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private int upperBound(java.util.List<Integer> values, int target) {
        int left = 0;
        int right = values.size();
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values.get(mid) <= target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}
